
const express = require('express');
const app = express();

app.use(express.json({ limit: '50mb' }));
app.use(express.urlencoded({ extended: true }));

app.use((req, res, next) => {

    res.setHeader('Content-Type', 'application/json');

    next();

});

app.get('/', (req, res) => {

    res.json({
        status: true,
        message: 'AI GENERATED SERVER'
    });

});



